class _ProcessOutputReader:
    """Drains the child's stdout/stderr pipes on daemon threads so the child
    never blocks on a full pipe."""

    def __init__(self, proc):
        import threading

        self._bufs = {"stdout": bytearray(), "stderr": bytearray()}
        self._threads = []
        for name, stream in (("stdout", proc.stdout), ("stderr", proc.stderr)):
            if stream is None:
                continue
            t = threading.Thread(
                target=self._drain, args=(name, stream), daemon=True
            )
            t.start()
            self._threads.append(t)

    @staticmethod
    def _drain(name, stream):
        buf = _ProcessOutputReader._current_bufs.get(name)
        if buf is None:
            return
        try:
            while True:
                chunk = stream.read(65536)
                if not chunk:
                    break
                buf.extend(chunk)
        except Exception:
            pass

    # the reader instance registers itself so the static drain sees its bufs
    _current_bufs = {}

    def __enter__(self):
        _ProcessOutputReader._current_bufs = self._bufs
        return self

    def __exit__(self, *exc):
        return False

    def join(self, timeout=2.0):
        deadline = time.time() + timeout
        for t in self._threads:
            remaining = deadline - time.time()
            if remaining <= 0:
                break
            t.join(remaining)

    def text(self, name):
        return _truncate(bytes(self._bufs.get(name, b"")).decode("utf-8", "replace"))

